const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Obolon, Ukraine geometry (district center, ~15km radius)
  const obolon = ee.Geometry.Point([30.55, 50.5]).buffer(15000);

  // 2. Load VIIRS Nighttime Lights Monthly data
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V21')
    .filterBounds(obolon);

  // 3. Filter for March 2022
  const march2022 = viirs
    .filterDate('2022-03-01', '2022-03-31')
    .select('avg_rad');

  // 4. Filter for May 2022
  const may2022 = viirs
    .filterDate('2022-05-01', '2022-05-31')
    .select('avg_rad');

  const marchSize = march2022.size().getInfo();
  const maySize = may2022.size().getInfo();

  print(`March 2022 Images: ${marchSize}`);
  print(`May 2022 Images: ${maySize}`);

  // 5. Check for empty collections
  if (marchSize === 0 || maySize === 0) {
    print("Missing data for one or both months.");
    print("C1");
    return;
  }

  // 6. Calculate mean radiance for March 2022
  const marchImg = march2022.first();
  const marchStats = marchImg.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: obolon,
    scale: 1000,
    maxPixels: 1e9
  });

  const marchMean = marchStats.getInfo()['avg_rad_mean'];
  const marchCount = marchStats.getInfo()['avg_rad_count'];

  // 7. Calculate mean radiance for May 2022
  const mayImg = may2022.first();
  const mayStats = mayImg.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: obolon,
    scale: 1000,
    maxPixels: 1e9
  });

  const mayMean = mayStats.getInfo()['avg_rad_mean'];
  const mayCount = mayStats.getInfo()['avg_rad_count'];

  print(`March 2022: Mean=${marchMean?.toFixed(3)}, Pixels=${marchCount}`);
  print(`May 2022: Mean=${mayMean?.toFixed(3)}, Pixels=${mayCount}`);

  // 8. Validate results
  if (marchCount === 0 || mayCount === 0) {
    print("No valid pixels in one or both months.");
    print("C2");
    return;
  }

  if (marchMean === null || mayMean === null || isNaN(marchMean) || isNaN(mayMean)) {
    print("Calculation resulted in invalid values.");
    print("C3");
    return;
  }

  // 9. Compare values
  const decreased = mayMean < marchMean;
  const difference = marchMean - mayMean;
  const percentChange = ((mayMean - marchMean) / marchMean * 100).toFixed(2);

  print(`Change: ${difference.toFixed(3)} (${percentChange}%)`);

  if (decreased) {
    print("A");
  } else {
    print("B");
  }
}

async function initEE() {
  return new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, () => {
      ee.initialize(null, null, () => {
        runAnalysis().then(resolve).catch(reject);
      }, reject);
    }, reject);
  });
}

initEE();
